#!/usr/bin/env python3
"""Make the 4.35 Reels controller aware of Android network validation, metering and power-save state."""
from pathlib import Path

OLD_DECL="""var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase(), networkOnline=navigator.onLine!==false, pressure=0, resumeTimer=0;
var conservative=!!conn.saveData;
try{var savedMode=localStorage.getItem('mm46-data-saver');if(savedMode==='1')conservative=true;else if(savedMode==='0')conservative=false;}catch(ignore){}
var fastNetwork=networkOnline&&!conservative&&!/^(slow-)?2g$/.test(networkType),releaseDelay=1100;"""
NEW_DECL="""var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase(), networkOnline=navigator.onLine!==false, networkValidated=true, networkMetered=false, downKbps=0, powerSaving=false, pressure=0, resumeTimer=0;
var conservative=!!conn.saveData;
try{var savedMode=localStorage.getItem('mm46-data-saver');if(savedMode==='1')conservative=true;else if(savedMode==='0')conservative=false;}catch(ignore){}
var fastNetwork=networkOnline&&networkValidated&&!networkMetered&&!powerSaving&&!conservative&&!/^(slow-)?2g$/.test(networkType),releaseDelay=1100;"""

OLD_MAY_PLAY="function mayPlay(){return !blocked();}"
NEW_MAY_PLAY="function mayPlay(){return !blocked()&&networkOnline&&networkValidated;}"

OLD_SAVER="saver.addEventListener('change',function(){conservative=saver.checked;fastNetwork=networkOnline&&!conservative&&!/^(slow-)?2g$/.test(networkType);try{localStorage.setItem('mm46-data-saver',conservative?'1':'0');}catch(ignore){}budget();});"
NEW_SAVER="saver.addEventListener('change',function(){conservative=saver.checked;recomputeNetwork();try{localStorage.setItem('mm46-data-saver',conservative?'1':'0');}catch(ignore){}budget();});"

OLD_BUDGET="function budget(){var i=cards.indexOf(active),keepAhead=pressure>=10?0:(fastNetwork&&memoryGb>=4?2:1);cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i;if(distance===0)attach(st,'auto','high');else if(distance===1)attach(st,fastNetwork?'auto':'metadata',fastNetwork?'high':'low');else if(distance===-1)attach(st,'metadata','low');else if(distance>1&&distance<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"
NEW_BUDGET="function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1);cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i;if(distance===0)attach(st,'auto','high');else if(distance===1)attach(st,constrained?'metadata':'auto',constrained?'low':'high');else if(distance===-1)attach(st,'metadata','low');else if(distance>1&&distance<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"

OLD_START="function start(st,user){if(!st||!mayPlay()||!networkOnline)return;if(!user&&(conservative||reduce.matches||st.userPaused))return;if(st.playPending)return;cards.forEach(function(c){var x=states.get(c);if(x&&x!==st){x.playToken++;x.playPending=false;x.v.pause();}});attach(st,'auto','high');st.v.muted=muted;st.card.removeAttribute('data-mm46-error');st.card.removeAttribute('data-mm433-slow');st.playPending=true;var token=++st.playToken,attempt=st.v.play();if(!attempt||typeof attempt.then!=='function'){st.playPending=false;return;}attempt.then(function(){if(token!==st.playToken)return;st.playPending=false;if(active!==st.card||!mayPlay()||!networkOnline)st.v.pause();else{st.userPaused=false;st.card.removeAttribute('data-mm46-blocked');budget();}}).catch(function(){if(token!==st.playToken)return;st.playPending=false;st.card.dataset.mm46Blocked='1';st.v.pause();});}"
NEW_START="function start(st,user){if(!st||!mayPlay())return;if(!user&&(conservative||reduce.matches||st.userPaused))return;if(st.playPending)return;cards.forEach(function(c){var x=states.get(c);if(x&&x!==st){x.playToken++;x.playPending=false;x.v.pause();}});attach(st,'auto','high');st.v.muted=muted;st.card.removeAttribute('data-mm46-error');st.card.removeAttribute('data-mm433-slow');st.playPending=true;var token=++st.playToken,attempt=st.v.play();if(!attempt||typeof attempt.then!=='function'){st.playPending=false;return;}attempt.then(function(){if(token!==st.playToken)return;st.playPending=false;if(active!==st.card||!mayPlay())st.v.pause();else{st.userPaused=false;st.card.removeAttribute('data-mm46-blocked');budget();}}).catch(function(){if(token!==st.playToken)return;st.playPending=false;st.card.dataset.mm46Blocked='1';st.v.pause();});}"

OLD_CONNECTION="""function connectionChanged(){networkType=String(conn.effectiveType||'').toLowerCase();fastNetwork=networkOnline&&!conservative&&!/^(slow-)?2g$/.test(networkType);budget();}
function networkChanged(){networkOnline=navigator.onLine!==false;fastNetwork=networkOnline&&!conservative&&!/^(slow-)?2g$/.test(networkType);if(!networkOnline)pauseAll();budget();if(networkOnline&&active&&!blocked())start(states.get(active),false);}
function memoryChanged(event){var level=event&&event.detail&&Number(event.detail.level);pressure=Number.isFinite(level)?level:0;budget();}
function foregroundChanged(){onResume();}
function backgroundChanged(){onSuspend();}"""
NEW_CONNECTION="""function recomputeNetwork(){fastNetwork=networkOnline&&networkValidated&&!networkMetered&&!powerSaving&&!conservative&&!/^(slow-)?2g$/.test(networkType)&&(downKbps<=0||downKbps>=1800);}
function connectionChanged(){networkType=String(conn.effectiveType||'').toLowerCase();recomputeNetwork();budget();}
function runtimeChanged(event){var d=event&&event.detail||{};window.__mm436NativeNetwork=true;if(Object.prototype.hasOwnProperty.call(d,'online'))networkOnline=!!d.online;if(Object.prototype.hasOwnProperty.call(d,'validated'))networkValidated=!!d.validated;if(Object.prototype.hasOwnProperty.call(d,'metered'))networkMetered=!!d.metered;if(Object.prototype.hasOwnProperty.call(d,'downKbps'))downKbps=Math.max(0,Number(d.downKbps)||0);if(Object.prototype.hasOwnProperty.call(d,'powerSave'))powerSaving=!!d.powerSave;recomputeNetwork();if(!networkOnline||!networkValidated)pauseAll();budget();if(networkOnline&&networkValidated&&active&&!blocked())start(states.get(active),false);}
function networkChanged(){networkOnline=navigator.onLine!==false;if(!window.__mm436NativeNetwork)networkValidated=networkOnline;recomputeNetwork();if(!networkOnline)pauseAll();budget();if(networkOnline&&networkValidated&&active&&!blocked())start(states.get(active),false);}
function powerChanged(event){var d=event&&event.detail||{};powerSaving=!!d.saving;recomputeNetwork();budget();}
function memoryChanged(event){var level=event&&event.detail&&Number(event.detail.level);pressure=Number.isFinite(level)?level:0;budget();}
function foregroundChanged(){onResume();}
function backgroundChanged(){onSuspend();}"""

OLD_EVENTS="feed.addEventListener('scroll',scrollFallback,{passive:true});window.addEventListener('mm45:suspend',onSuspend);window.addEventListener('mm45:resume',onResume);window.addEventListener('mmapp:memory',memoryChanged);window.addEventListener('mmapp:foreground',foregroundChanged);window.addEventListener('mmapp:background',backgroundChanged);window.addEventListener('online',networkChanged);window.addEventListener('offline',networkChanged);window.addEventListener('mm435:network',networkChanged);document.addEventListener('visibilitychange',visibility);document.addEventListener('keydown',keys);window.addEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.addEventListener('resize',dimensions);if(conn&&conn.addEventListener)conn.addEventListener('change',connectionChanged);"
NEW_EVENTS="feed.addEventListener('scroll',scrollFallback,{passive:true});window.addEventListener('mm45:suspend',onSuspend);window.addEventListener('mm45:resume',onResume);window.addEventListener('mmapp:memory',memoryChanged);window.addEventListener('mmapp:foreground',foregroundChanged);window.addEventListener('mmapp:background',backgroundChanged);window.addEventListener('mmapp:runtime',runtimeChanged);window.addEventListener('mmapp:network',runtimeChanged);window.addEventListener('mmapp:power',powerChanged);window.addEventListener('online',networkChanged);window.addEventListener('offline',networkChanged);window.addEventListener('mm435:network',networkChanged);document.addEventListener('visibilitychange',visibility);document.addEventListener('keydown',keys);window.addEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.addEventListener('resize',dimensions);if(conn&&conn.addEventListener)conn.addEventListener('change',connectionChanged);"

OLD_DESTROY="function destroy(){disposed=true;clearTimeout(resumeTimer);pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();clearTimeout(scrollTimer);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"
NEW_DESTROY="function destroy(){disposed=true;clearTimeout(resumeTimer);pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();clearTimeout(scrollTimer);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"

REPLACEMENTS=[
 (OLD_DECL,NEW_DECL),(OLD_MAY_PLAY,NEW_MAY_PLAY),(OLD_SAVER,NEW_SAVER),
 (OLD_BUDGET,NEW_BUDGET),(OLD_START,NEW_START),(OLD_CONNECTION,NEW_CONNECTION),
 (OLD_EVENTS,NEW_EVENTS),(OLD_DESTROY,NEW_DESTROY),
]

def patch_controller(path:Path)->None:
    text=path.read_text(encoding='utf-8')
    for old,new in REPLACEMENTS:
        count=text.count(old)
        assert count==1,f'{path}: expected one 4.35 anchor, found {count}: {old[:100]!r}'
        text=text.replace(old,new,1)
    path.write_text(text,encoding='utf-8')
